CREATE TABLE `customers` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uid` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `company_id` bigint(20) unsigned DEFAULT NULL,
  `currency_id` bigint(20) unsigned DEFAULT NULL,
  `acc_main` varchar(11) COLLATE utf8mb4_unicode_ci NOT NULL,
  `acc_sub` varchar(3) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000',
  `CustomerName` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `BillToCustomerID` bigint(20) unsigned DEFAULT NULL,
  `CustomerCategoryID` bigint(20) unsigned DEFAULT NULL,
  `BuyingGroupID` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `PrimaryContactPersonID` bigint(20) unsigned DEFAULT NULL,
  `AlternateContactPersonID` bigint(20) unsigned DEFAULT NULL,
  `StoreEAN` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `VatNr` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `CreditLimit` decimal(18,2) DEFAULT NULL,
  `AccountOpenedDate` date DEFAULT NULL,
  `StandardDiscountPercentage` decimal(18,3) DEFAULT NULL,
  `IsStatementSent` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `IsOnCreditHold` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `PaymentDays` bigint(20) unsigned DEFAULT NULL,
  `PhoneNumber` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `FaxNumber` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `DeliveryRoute` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `DeliveryRoutePosition` varchar(5) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `WebsiteURL` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `GeneralEmailAddress` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `DeliveryAddressLine1` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `DeliveryAddressLine2` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `DeliveryCity` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `DeliveryPostalCode` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `PostalAddressLine1` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `PostalAddressLine2` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `PostalCity` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `PostalPostalCode` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `CustomerStatus` tinyint(1) unsigned NOT NULL DEFAULT 1,
  `CountryID` bigint(20) unsigned NOT NULL DEFAULT 215,
  `SalesRepID` bigint(20) unsigned DEFAULT NULL,
  `LastEditedBy` bigint(20) unsigned NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `customers_acc_main_unique` (`acc_main`),
  UNIQUE KEY `customers_customername_unique` (`CustomerName`),
  UNIQUE KEY `customers_uid_unique` (`uid`),
  KEY `customers_acc_main_storeean_index` (`acc_main`,`StoreEAN`),
  KEY `customers_countryid_foreign` (`CountryID`),
  KEY `customers_salesrepid_foreign` (`SalesRepID`),
  KEY `customers_billtocustomerid_foreign` (`BillToCustomerID`),
  KEY `customers_buyinggroupid_foreign` (`BuyingGroupID`),
  KEY `customers_customercategoryid_foreign` (`CustomerCategoryID`),
  KEY `customers_primarycontactpersonid_foreign` (`PrimaryContactPersonID`),
  KEY `customers_alternatecontactpersonid_foreign` (`AlternateContactPersonID`),
  KEY `customers_storeean_unique` (`StoreEAN`) USING BTREE,
  KEY `customers_company_id_foreign` (`company_id`),
  KEY `customers_currency_id_foreign` (`currency_id`),
  CONSTRAINT `customers_alternatecontactpersonid_foreign` FOREIGN KEY (`AlternateContactPersonID`) REFERENCES `users` (`id`),
  CONSTRAINT `customers_billtocustomerid_foreign` FOREIGN KEY (`BillToCustomerID`) REFERENCES `customers` (`id`),
  CONSTRAINT `customers_company_id_foreign` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`) ON DELETE CASCADE,
  CONSTRAINT `customers_countryid_foreign` FOREIGN KEY (`CountryID`) REFERENCES `countries` (`id`),
  CONSTRAINT `customers_currency_id_foreign` FOREIGN KEY (`currency_id`) REFERENCES `currencies` (`id`) ON DELETE CASCADE ON UPDATE NO ACTION,
  CONSTRAINT `customers_customercategoryid_foreign` FOREIGN KEY (`CustomerCategoryID`) REFERENCES `customer_categories` (`id`),
  CONSTRAINT `customers_primarycontactpersonid_foreign` FOREIGN KEY (`PrimaryContactPersonID`) REFERENCES `users` (`id`),
  CONSTRAINT `customers_salesrepid_foreign` FOREIGN KEY (`SalesRepID`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=100068 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
